from collections import Counter

def transform(grid):
    g=[row[:] for row in grid]
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    # The key is a vertical strip of color/fill pairs in one column.
    # Find the column containing several adjacent non-background 2-cell rows.
    key={}
    for c in range(len(grid[0])-1):
        candidate={}
        for r in range(len(grid)-1):
            a,x=grid[r][c],grid[r][c+1]
            if a!=bg and a!=x:
                candidate[a]=x
        if len(candidate)>len(key):
            key=candidate
    for color in sorted(key, reverse=True):
        cells=[(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==color]
        # Valid markers consist of exactly six cells (two L triominoes).
        if len(cells)!=6:
            continue
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        fill=key[color]
        for r in range(min(rs),max(rs)+1):
            for c in range(min(cs),max(cs)+1):
                if g[r][c]==bg or g[r][c] in key:
                    # Only replace original background, never a marker.
                    if grid[r][c]==bg:
                        g[r][c]=fill
    return g

